import{_ as t,a,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"Admin Workflows","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/workflows/admin/index.md","filePath":"api/workflows/admin/index.md","lastUpdated":1784902076000}'),n={name:"api/workflows/admin/index.md"};function i(s,e,d,l,c,h){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="admin-workflows" tabindex="-1">Admin Workflows <a class="header-anchor" href="#admin-workflows" aria-label="Permalink to &quot;Admin Workflows&quot;">​</a></h1><p>The back-office call-sequences — how a client drives the Admin API (<code>/api/admin/*</code> REST + <code>POST /api/admin/graphql</code>) to rebuild any admin-panel screen. The Admin API mirrors the admin panel <strong>menu-for-menu</strong>.</p><h2 id="agent-ask-inputs" tabindex="-1">Agent-ask inputs <a class="header-anchor" href="#agent-ask-inputs" aria-label="Permalink to &quot;Agent-ask inputs&quot;">​</a></h2><ul><li><strong>Integration token</strong> — ask the user for a pre-issued admin Integration token (generated in the admin panel&#39;s Integration menu). Send it as <code>Authorization: Bearer &lt;id&gt;|&lt;token&gt;</code>. There is no admin login; the agent never mints this token.</li><li><strong>Server URL</strong> — ask the user for their Bagisto server&#39;s base URL (e.g. <code>https://store.example.com</code>) and prefix every endpoint path with it. Never assume localhost or a demo domain.</li></ul><h2 id="the-core-pattern-list-→-detail-→-action" tabindex="-1">The core pattern: list → detail → action <a class="header-anchor" href="#the-core-pattern-list-→-detail-→-action" aria-label="Permalink to &quot;The core pattern: list → detail → action&quot;">​</a></h2><p>Almost every admin screen is the same shape:</p><ul><li><strong>List</strong> — <code>GET /api/admin/&lt;resource&gt;</code> → a <code>{ data, meta }</code> envelope. Drive tables with <code>?page=</code> + <code>?per_page=</code> (default 10, cap 50) + the screen&#39;s filters. Page-count headers: <code>X-Total-Count</code>, <code>X-Page</code>, <code>X-Per-Page</code>, <code>X-Total-Pages</code>.</li><li><strong>Detail</strong> — <code>GET /api/admin/&lt;resource&gt;/{id}</code> → the full record with relations embedded (no follow-up calls).</li><li><strong>Action</strong> — <code>POST</code> / <code>PUT</code> / <code>DELETE</code> for create/update/delete plus per-record actions (cancel order, create invoice, mass-update, …). Each action has its own eligibility rules and permission gate — a forbidden action returns <strong>403</strong>.</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><strong><a href="/api/workflows/admin/build-an-admin-dashboard.html">Build an Admin Dashboard</a></strong> — the complete blueprint: every admin menu (Sales, Catalog, Customers, Marketing, CMS, Settings, Configuration, Dashboard/Reporting) mapped to its API. Read this for the whole picture.</li></ul><h2 id="complicated-flows-with-theory" tabindex="-1">Complicated flows (with theory) <a class="header-anchor" href="#complicated-flows-with-theory" aria-label="Permalink to &quot;Complicated flows (with theory)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>Why it needs its own page</th></tr></thead><tbody><tr><td><a href="/api/workflows/admin/create-order-flow.html">Create-Order Flow</a></td><td>A strict sequential draft-cart state machine (409 on wrong step), booking-blocked, non-saleable guard, action-results have no selectable <code>id</code>.</td></tr><tr><td><a href="/api/workflows/admin/product-management.html">Product Management</a></td><td>Attributes → families → product schema chain, two-step create (7 types, <code>super_attributes</code>), partial-update wipe traps, image/inventory/price sub-panels.</td></tr><tr><td><a href="/api/workflows/admin/order-fulfillment-actions.html">Order Fulfillment Actions</a></td><td>Invoice/ship/refund/cancel eligibility guards, PayPal-invoice block, per-SKU qty, inventory-at-source, <code>canCreateTransaction</code>.</td></tr><tr><td><a href="/api/workflows/admin/customers.html">Customers (Impersonate &amp; GDPR)</a></td><td>Impersonate issues a short-lived customer token; GDPR process cascades a delete; download-data dumps every related table.</td></tr><tr><td><a href="/api/workflows/admin/marketing.html">Marketing</a></td><td>Catalog-rule reindex timeout on a <code>sync</code> queue, campaign send (recipient resolution + status guard), coupon generate, sitemap sync-generate.</td></tr><tr><td><a href="/api/workflows/admin/configuration.html">Configuration</a></td><td>Generic slug-scoped schema/values/update, anti-scope-escape, server-side validation, file-upload REST-only.</td></tr></tbody></table><h2 id="graphql-—-the-must-know-rules" tabindex="-1">GraphQL — the must-know rules <a class="header-anchor" href="#graphql-—-the-must-know-rules" aria-label="Permalink to &quot;GraphQL — the must-know rules&quot;">​</a></h2><ul><li><strong>Separate endpoint:</strong> <code>POST /api/admin/graphql</code>, admin token only, <strong>no</strong> storefront key (the shop and admin GraphQL endpoints don&#39;t share a schema).</li><li><strong>Result-field / <code>id</code> rule (most common mistake):</strong> fetchable resources (order, product, customer…) expose <code>id</code> + <code>_id</code>; <strong>action / result mutations</strong> (cancel, create invoice/shipment/refund, place order, cart writes, mass-actions) return a <strong>result object</strong> — select the documented result fields (<code>success</code>, <code>message</code>, <code>orderId</code>, <code>cartId</code>, …), not a generic <code>id</code>.</li><li><strong>Inputs are camelCase</strong> (<code>customerId</code>, <code>orderId</code>, <code>indices</code>). Custom list filters are explicit per-query args (use the names the endpoint page shows — not auto-discoverable).</li><li><strong>Collections use cursor pagination</strong> (<code>first</code> / <code>after</code> / <code>edges { node }</code> / <code>pageInfo</code>); REST uses the <code>{ data, meta }</code> envelope instead.</li><li><strong>Nested lists</strong> (order items, invoice items, addresses) are often <strong>plain JSON</strong>, not connections — query them as bare fields (<code>items { sku qtyOrdered }</code>), following the endpoint&#39;s docs example.</li></ul><h2 id="how-to-read-a-flow-page" tabindex="-1">How to read a flow page <a class="header-anchor" href="#how-to-read-a-flow-page" aria-label="Permalink to &quot;How to read a flow page&quot;">​</a></h2><p>Intent → Agent-ask inputs → the flow/diagram → ordered calls (links to the exact endpoint pages) → theory/gotchas. Flow pages own the sequence and the non-obvious behavior; endpoint detail lives on the linked API pages.</p>',15)]))}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
